'use client'

import { useState } from 'react'
import { Filter } from 'lucide-react'
import { getColorForType } from '@/utils/utils'

export default function FiltresLieux({ categories, villes, filtresActifs, setFiltresActifs }) {
  const [showFilters, setShowFilters] = useState(false)

  const toggleFiltre = (type, value) => {
    setFiltresActifs(prev => {
      const arr = prev[type]
      const newArr = arr.includes(value)
        ? arr.filter(v => v !== value)
        : [...arr, value]
      return { ...prev, [type]: newArr }
    })
  }

  const totalFiltres = filtresActifs.types.length + filtresActifs.villes.length

  return (
    <div className="bg-white rounded-lg shadow-sm p-4 mb-6">
      <button
        onClick={() => setShowFilters(!showFilters)}
        className={`w-full flex items-center justify-between px-4 py-2 rounded-lg ${
          showFilters ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-700'
        }`}
      >
        <div className="flex items-center gap-2">
          <Filter size={20} />
          <span>Filtres</span>
          {totalFiltres > 0 && (
            <span className="bg-white text-blue-600 rounded-full w-6 h-6 flex items-center justify-center text-sm font-bold">
              {totalFiltres}
            </span>
          )}
        </div>
      </button>

      {showFilters && (
        <div className="bg-gray-50 p-4 rounded-lg mt-4 border">
          <div className="grid md:grid-cols-2 gap-6">
            {/* Filtres Types */}
            <div>
              <h3 className="font-medium mb-2">Types</h3>
              <div className="flex flex-wrap gap-2">
                {categories.map(cat => (
                  <button
                    key={cat}
                    onClick={() => toggleFiltre('types', cat)}
                    className={`px-3 py-1 rounded-full text-sm transition-colors ${
                      filtresActifs.types.includes(cat)
                        ? 'bg-blue-600 text-white'
                        : 'bg-white border'
                    }`}
                    onMouseEnter={(e) => {
                      if (!filtresActifs.types.includes(cat)) {
                        e.currentTarget.style.backgroundColor = getColorForType(cat)
                        e.currentTarget.style.color = '#202020ff'
                      }
                    }}
                    onMouseLeave={(e) => {
                      if (!filtresActifs.types.includes(cat)) {
                        e.currentTarget.style.backgroundColor = 'white'
                        e.currentTarget.style.color = ''
                      }
                    }}
                  >
                    {cat}
                  </button>
                ))}
              </div>
            </div>

            {/* Filtres Villes */}
            <div>
              <h3 className="font-medium mb-2">Villes</h3>
              <div className="flex flex-wrap gap-2">
                {villes.map(ville => (
                  <button
                    key={ville.id || ville.nom}
                    onClick={() => toggleFiltre('villes', ville.nom)}
                    className={`px-3 py-1 rounded-full text-sm ${
                      filtresActifs.villes.includes(ville.nom)
                        ? 'bg-blue-600 text-white'
                        : 'bg-white border hover:bg-gray-100'
                    }`}
                  >
                    {ville.nom}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}